test("creates a job with JD and reference URL, then switches views", async ({ page }) => {
  await page.goto("/");
  await expect(page.locator("#application-board-title")).toHaveText("职位申请");
  await page.getByRole("textbox", { name: "公司", exact: true }).fill("E2E 公司");
