  if (Notification.permission === "denied") return "浏览器通知已被拒绝；应用内提醒和 ICS 导出仍可用。";
  if (Notification.permission === "granted") return "浏览器通知已授权；应用内提醒和 ICS 导出仍可用。";
  return "浏览器通知尚未授权；应用内提醒和 ICS 导出仍可用。";
}

