ent; const custom = form.elements.namedItem("customReminder") as HTMLInputElement; preset.value = reminder && [10, 30, 60, 1440].includes(reminder.offsetMinutes) ? String(reminder.offsetMinutes) : "custom"; custom.value = String(reminder?.offsetMinutes ?? 30); (form.elements.namedItem("inAppReminder") as HTMLInputElement).checked = interview.reminders.some((item) => item.channel === "in-app"); (form.elements.namedItem("browserReminder") as HTMLInputElement).checked = interview.reminders.some((item) => item.channel === "browser"); (form.querySelector("[data-form-title]") as HTMLElement).textContent = "编辑面试"; (form.querySelector('[data-action="cancel-edit"]') as HTMLButtonElement).hidden = false; form.scrollIntoView({ block: "start" }); status.textContent = "已载入面试编辑，尚未保存"; return; } else if (button.dataset.action === "export-ics") { if (!options.exportInterviewICS) throw new Error("当前无法导出 ICS"); const ics = await options.exportInterviewICS(id); const anchorElement = documentRef.createElement("a"); anchorElement.download = `${interview.title || "interview"}.ics`; anchorElement.href = `data:text/calendar;charset=utf-8,${encodeURIComponent(ics)}`; documentRef.body.append(anchorElement); anchorElement.click(); anchorElement.remove(); status.textContent = "ICS 已准备下载"; return; } await refresh(); status.textContent = button.dataset.action === "cancel" ? "面试已取消" : "面试已完成"; root.dispatchEvent(new CustomEvent("interview-updated", { detail: id, bubbles: true })); } catch { status.textContent = "操作失败，资料未改变；可重试"; } });
