    const aiSection = options.aiAdvisorService ? `<section class="ai-advisor-panel" aria-labelledby="ai-advisor-title"><h4 id="ai-advisor-title">AI 顾问</h4><form data-ai-form><label for="ai-prompt">咨询问题<textarea id="ai-prompt" name="prompt" rows="3" required placeholder="例如：如何突出与职位相关的项目？"></textarea></label><button type="submit" data-action="open-ai-preview">预览并发送</button></form><p class="ai-status" role="status" aria-live="polite"></p>${activeAdvisorResult ? renderAiResult(activeAdvisorResult) : ""}<div class="ai-conversation">${(conversation?.messages ?? []).filter((message) => message.role !== "system").map((message) => `<article data-message-id="${esc(message.id)}"><p><strong>${message.role === "user" ? "我" : "AI"}</strong></p><p class="ai-message-content">${esc(message.content)}</p><button type="button" data-action="copy-ai-message" data-message="${esc(message.content)}">复制此段</button></article>`).join("")}</div>${conversation?.messages.length ? `<button type="button" data-action="copy-ai-all">复制全部</button><button type="button" data-action="export-ai-report">导出优化报告</button>` : ""}</section>` : "";
    detailContent.innerHTML = `<dl class="application-detail__facts"><dt>公司</dt><dd>${esc(item.company)}</dd><dt>职位</dt><dd>${esc(item.position)}</dd><dt>阶段</dt><dd>${esc(stageById(item.stageId)?.name ?? "")}</dd><dt>网址</dt><dd>${item.jobUrl ? `<a href="${esc(item.jobUrl)}" target="_blank" rel="noreferrer">${esc(item.jobUrl)}</a>` : "未填写"}</dd><dt>JD</dt><dd class="application-long-text">${esc(item.jdText || "未确认 JD")}</dd></dl><div class="application-detail__actions"><label>推进阶段<select data-detail-stage>${stages.map((stage) => `<option value="${esc(stage.id)}" ${stage.id === item.stageId ? "selected" : ""}>${esc(stage.name)}</option>`).join("")}</select></label><button type="button" data-action="save-detail-stage">保存阶段</button><label>切换当前简历<select data-detail-resume><option value="">未绑定</option>${resumes.filter((resume) => resume.status !== "deleted").map((resume) => `<option value="${esc(resume.id)}" ${resume.id === item.currentResumeId ? "selected" : ""}>${esc(resume.name)}</option>`).join("")}</select></label><button type="button" data-action="save-detail-resume">保存简历</button><label>添加备注<textarea data-detail-note rows="2">${esc(item.note)}</textarea></label><button type="button" data-action="save-detail-note">保存备注</button><button type="button" data-action="archive" data-application-id="${esc(id)}">归档</button><button type="button" data-action="delete" data-application-id="${esc(id)}">删除职位</button></div><section class="matching-panel" aria-labelledby="matching-panel-title"><h4 id="matching-panel-title">本地 JD 匹配</h4>${options.matchingService ? `<div class="matching-run-controls"><label>用于匹配的简历<select data-matching-resume>${resumes.filter((resume) => resume.status !== "deleted").map((resume) => `<option value="${esc(resume.id)}" ${resume.id === item.currentResumeId ? "selected" : ""}>${esc(resume.name)}</option>`).join("")}</select></label><button type="button" data-action="run-matching" data-application-id="${esc(id)}">运行匹配</button></div>` : ""}<p class="matching-status" role="status" aria-live="polite"></p><div class="matching-history">${analysisHistory.length ? analysisHistory.map((result) => `<button type="button" class="matching-history__item" data-action="open-analysis" data-analysis-id="${esc(result.id)}">${esc(result.createdAt)} · ${esc(resumes.find((resume) => resume.id === result.resumeId)?.name ?? result.resumeId)}</button>`).join("") : "<p>暂无匹配历史</p>"}</div><div class="matching-current">${analysisHistory[0] ? renderResult(analysisHistory[0]) : ""}</div></section>${aiSection}<h4>简历使用历史</h4><ul>${history.map((entry) => `<li>${esc(entry.resumeNameSnapshot)}：${esc(entry.textSnapshot)}</li>`).join("") || "<li>暂无历史</li>"}</ul><h4>时间线</h4><ol>${timeline.map((entry) => `<li>${esc(entry.type)}：${esc(entry.note)}</li>`).join("") || "<li>暂无事件</li>"}</ol>`;
