export interface ResumeExtractionRecovery {
  code: "extraction-failed";
  action: ResumeRecoveryAction;
  metadata: ResumeFileMetadata;
}

export interface ResumeIngestionResult {
  outcome: "needs-review" | "extraction-failed";
