    validateBackupPayload(payload, input.kind);
    return payload;
  } catch (error) {
    if (error instanceof Error && /Invalid backup|Unsupported backup|mismatch/.test(error.message)) throw error;
    throw new Error("Unable to decrypt backup");
  }
